      if (lookahead == '"') { lexer->get_position(lexer, &start_tags[0]); ADVANCE(295); }
      if (lookahead == '#') { lexer->get_position(lexer, &start_tags[0]); ADVANCE(36); }
      if (lookahead == '$') { lexer->get_position(lexer, &start_tags[0]); ADVANCE(456); }
      if (lookahead == '%') { lexer->get_position(lexer, &start_tags[0]); ADVANCE(369); }
      if (lookahead == '&') { lexer->get_position(lexer, &start_tags[0]); ADVANCE(347); }
      if (lookahead == '\'') { lexer->get_position(lexer, &start_tags[0]); ADVANCE(296); }
      if (lookahead == '(') { lexer->get_position(lexer, &start_tags[0]); ADVANCE(275); }
